def copiar_documentos_matrimonio(apps, schema_editor):
    DocumentoMatrimonio = apps.get_model("sacramentos", "DocumentoMatrimonio")
    DocumentoSacramento = apps.get_model("sacramentos", "DocumentoSacramento")
    for documento in DocumentoMatrimonio.objects.all().iterator():
        DocumentoSacramento.objects.create(
            sacramento_id=documento.matrimonio_id,
            descripcion=documento.descripcion,
            archivo=documento.archivo.name,
        )


